    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BackendPreference {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .auto
        
        case 2: return .cpu
        
        case 3: return .gpu
        
        case 4: return .metal
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BackendPreference, into buf: inout [UInt8]) {
        switch value {
        
        
        case .auto:
            writeInt(&buf, Int32(1))
        
        
        case .cpu:
            writeInt(&buf, Int32(2))
        
        
        case .gpu:
            writeInt(&buf, Int32(3))
        
        
        case .metal:
            writeInt(&buf, Int32(4))
        
        }
    }
}


